    internal static int Category(int codePoint)
    {
        var low = 0;
        var high = Ranges.Length / 3 - 1;
        while (low <= high)
        {
            var middle = (low + high) >> 1;
            var start = Ranges[middle * 3];
            var end = Ranges[middle * 3 + 1];
            if (codePoint < start) high = middle - 1;
            else if (codePoint > end) low = middle + 1;
            else return Ranges[middle * 3 + 2];
        }
        return 0;
    }

    internal static bool IsLinker(int codePoint) => Array.BinarySearch(Linkers, codePoint) >= 0;
